define(function () {
    'use strict';

    function ContextMenu(map) {
        this.map = map;
        this.menuId = 'mapContextMenu';
    }

    // 显示菜单
    ContextMenu.prototype.show = function (items) {
        var event = window.event;
        var clientX = event.clientX - this.map.container.offsetLeft;
        var clientY = event.clientY - this.map.container.offsetTop;
        // 删除原菜单
        this.remove();
        // 创建新菜单
        var menu = document.createElement('div');
        menu.id = this.id;
        menu.className = 'mapContextMenu';
        menu.oncontextmenu = function () { return false; };// 禁用操作系统菜单
        this.map.container.appendChild(menu);
        var ul = document.createElement('ul');
        menu.appendChild(ul);
        // 创建菜单项
        items.forEach(item => {
            var li = document.createElement('li');
            li.innerText = item.name;
            li.onclick = () => {
                item.click();
                this.remove();
            }
            ul.appendChild(li);
        });
        // 设置菜单位置
        var rightEdge = this.map.container.clientWidth - clientX;
        var bottomEdge = this.map.container.clientHeight - clientY;
        if (rightEdge < menu.offsetWidth) {
            Object.assign(menu.style, { right: `${rightEdge}px` });// menu.style.right = rightEdge;
        } else {
            Object.assign(menu.style, { left: `${clientX}px` });// menu.style.left = clientX;
        }
        if (bottomEdge < menu.offsetHeight) {
            Object.assign(menu.style, { bottom: `${bottomEdge}px` });// menu.style.bottom = bottomEdge;
        } else {
            Object.assign(menu.style, { top: `${clientY}px` });// menu.style.top = clientY;
        }
    }

    // 删除菜单
    ContextMenu.prototype.remove = function () {
        var menu = document.getElementById(this.id);
        if (menu) {
            this.map.container.removeChild(menu);
        }
    }

    return ContextMenu;
});
