define(function () {
    'use strict';

    var Convert = {};

    // 世界坐标转屏幕坐标
    Convert.worldToScreen = function (map, world) {
        return Cesium.SceneTransforms.wgs84ToWindowCoordinates(map.scene, this.getPositionCartesian(world));
    };

    // 屏幕坐标转世界坐标
    Convert.screenToWorld = function (map, point) {
        // return map.scene.globe.pick(map.camera.getPickRay(point), map.scene);
        var carte1 = map.scene.pickPosition(point);// 拾取模型
        var carte2 = map.scene.globe.pick(map.camera.getPickRay(point), map.scene);// 拾取地形
        if (!carte1 && !carte2) return undefined;
        carte1 = carte1 || Cesium.Cartesian3.ZERO;
        carte2 = carte2 || Cesium.Cartesian3.ZERO;
        return Cesium.Cartesian3.magnitude(carte1) > Cesium.Cartesian3.magnitude(carte2) ? carte1 : carte2;
    };

    // 两点计算Heading
    Convert.getHeading = function (pointA, pointB) {
        //建立以点A为原点，X轴为east,Y轴为north,Z轴朝上的坐标系
        const transform = Cesium.Transforms.eastNorthUpToFixedFrame(pointA);
        //向量AB
        const positionvector = Cesium.Cartesian3.subtract(pointB, pointA, new Cesium.Cartesian3());
        //因transform是将A为原点的eastNorthUp坐标系中的点转换到世界坐标系的矩阵
        //AB为世界坐标中的向量
        //因此将AB向量转换为A原点坐标系中的向量，需乘以transform的逆矩阵。
        const vector = Cesium.Matrix4.multiplyByPointAsVector(Cesium.Matrix4.inverse(transform, new Cesium.Matrix4()), positionvector, new Cesium.Cartesian3());
        //归一化
        const direction = Cesium.Cartesian3.normalize(vector, new Cesium.Cartesian3());
        //heading
        const heading = Math.atan2(direction.y, direction.x) - Cesium.Math.PI_OVER_TWO;
        return Cesium.Math.TWO_PI - Cesium.Math.zeroToTwoPi(heading);
    }

    // 两点计算Pitch
    Convert.getPitch = function (pointA, pointB) {
        let transfrom = Cesium.Transforms.eastNorthUpToFixedFrame(pointA);
        const vector = Cesium.Cartesian3.subtract(pointB, pointA, new Cesium.Cartesian3());
        let direction = Cesium.Matrix4.multiplyByPointAsVector(Cesium.Matrix4.inverse(transfrom, transfrom), vector, vector);
        Cesium.Cartesian3.normalize(direction, direction);
        //因为direction已归一化，斜边长度等于1，所以余弦函数等于direction.z
        return Cesium.Math.PI_OVER_TWO - Cesium.Math.acosClamped(direction.z);
    }

    // 转换颜色
    Convert.getCesiumColor = function (value) {
        if (value instanceof Cesium.Color) {
            return value;
        } else if (typeof value == "string") {
            return Cesium.Color.fromCssColorString(value);
        } else if (typeof value == "object") {
            return new Cesium.Color(value.red, value.green, value.blue, value.alpha);
        }
    }

    // 角度数组转换Cesium.HeadingPitchRoll
    Convert.getCesiumHpr = function (value) {
        if (value instanceof Array && value.length > 2 && typeof value[0] == "number") {
            return Cesium.HeadingPitchRoll.fromDegrees(value[0], value[1], value[2], new Cesium.HeadingPitchRoll);
        }
        return value;
    }

    // 获取坐标
    Convert.getPositionCartesian = function (value) {
        if (value instanceof Array && value.length > 2 && typeof value[0] == "number") {
            return Cesium.Cartesian3.fromDegrees(value[0], value[1], value[2])
        } else if (value instanceof Cesium.Cartographic) {
            return Cesium.Cartesian3.fromRadians(value.longitude, value.latitude, value.height);
        } else {
            return value;
        }
    }

    // 获取坐标
    Convert.getPositionCartographic = function (value) {
        if (value instanceof Array && value.length > 2 && typeof value[0] == "number") {
            return Cesium.Cartographic.fromDegrees(value[0], value[1], value[2])
        } else if (value instanceof Cesium.Cartesian3) {
            return Cesium.Cartographic.fromCartesian(value);
        } else {
            return value;
        }
    }

    // 获取坐标
    Convert.getPositionDegree = function (value) {
        var carto = undefined;
        if (value instanceof Cesium.Cartesian3) {
            carto = Cesium.Cartographic.fromCartesian(value);
        } else if (value instanceof Cesium.Cartographic) {
            carto = value;
        }
        return carto ? [Cesium.Math.toDegrees(carto.longitude), Cesium.Math.toDegrees(carto.latitude), carto.height] : value;
    }

    // 转换坐标串
    Convert.getPositions = function (value) {
        if (value instanceof Array && value.length > 5 && typeof value[0] == "number") {
            return Cesium.Cartesian3.fromDegreesArrayHeights(value)
        } else {
            return value;
        }
    }

    // 转换options参数
    Convert.getOptions = function (obj) {
        for (var key in obj) {
            if (!obj.hasOwnProperty(key)) continue;
            var value = obj[key];
            if (key == "position") {
                if (value instanceof Array && value.length > 2 && typeof value[0] == "number") {
                    obj[key] = Cesium.Cartesian3.fromDegrees(value[0], value[1], value[2])
                }
            } else if (key == "positions") {
                if (value instanceof Array && value.length > 5 && typeof value[0] == "number") {
                    obj[key] = Cesium.Cartesian3.fromDegreesArrayHeights(value)
                }
            } else if (key == "color") {
                if (typeof value == "string") {
                    obj[key] = Cesium.Color.fromCssColorString(value);
                }
            } else if (key == "material") {
                var cls = new Function("return " + value.type)();
                var opts = this.getOptions(value.options);
                if (cls && opts) {
                    obj[key] = new cls(opts);
                }
            } else if (typeof value == "object") {
                obj[key] = this.getOptions(value);
            }
        }
        return obj;
    }

    const x_PI = 3.14159265358979324 * 3000.0 / 180.0;
    const PI = 3.1415926535897932384626;
    const a = 6378245.0;
    const ee = 0.00669342162296594323;
    // 百度坐标系 (BD-09) 与 火星坐标系 (GCJ-02)的转换[谷歌、高德]
    function bd09togcj02(bd_lon, bd_lat) {
        var x = bd_lon - 0.0065;
        var y = bd_lat - 0.006;
        var z = Math.sqrt(x * x + y * y) - 0.00002 * Math.sin(y * x_PI);
        var theta = Math.atan2(y, x) - 0.000003 * Math.cos(x * x_PI);
        var gg_lng = z * Math.cos(theta);
        var gg_lat = z * Math.sin(theta);
        return [gg_lng, gg_lat];
    }
    // 火星坐标系 (GCJ-02) 与百度坐标系 (BD-09) 的转换
    function gcj02tobd09(lng, lat) {
        var z = Math.sqrt(lng * lng + lat * lat) + 0.00002 * Math.sin(lat * x_PI);
        var theta = Math.atan2(lat, lng) + 0.000003 * Math.cos(lng * x_PI);
        var bd_lng = z * Math.cos(theta) + 0.0065;
        var bd_lat = z * Math.sin(theta) + 0.006;
        return [bd_lng, bd_lat];
    };
    // WGS84转GCj02
    function wgs84togcj02(lng, lat) {
        var dlat = transformlat(lng - 105.0, lat - 35.0);
        var dlng = transformlng(lng - 105.0, lat - 35.0);
        var radlat = lat / 180.0 * PI;
        var magic = Math.sin(radlat);
        magic = 1 - ee * magic * magic;
        var sqrtmagic = Math.sqrt(magic);
        dlat = (dlat * 180.0) / ((a * (1 - ee)) / (magic * sqrtmagic) * PI);
        dlng = (dlng * 180.0) / (a / sqrtmagic * Math.cos(radlat) * PI);
        var mglat = lat + dlat;
        var mglng = lng + dlng;
        return [mglng, mglat];
    };
    // GCJ02 转换为 WGS84
    function gcj02towgs84(lng, lat) {
        var dlat = transformlat(lng - 105.0, lat - 35.0);
        var dlng = transformlng(lng - 105.0, lat - 35.0);
        var radlat = lat / 180.0 * PI;
        var magic = Math.sin(radlat);
        magic = 1 - ee * magic * magic;
        var sqrtmagic = Math.sqrt(magic);
        dlat = (dlat * 180.0) / ((a * (1 - ee)) / (magic * sqrtmagic) * PI);
        dlng = (dlng * 180.0) / (a / sqrtmagic * Math.cos(radlat) * PI);
        var mglat = lat + dlat;
        var mglng = lng + dlng;
        return [lng * 2 - mglng, lat * 2 - mglat];// return [mglng, mglat];
    };
    // WGS84 转换为 BD-09
    function wgs84tobd09(lng, lat) {
        var ret = wgs84togcj02(lng, lat);
        return gcj02tobd09(ret[0], ret[1]);
    }
    // BD-09 转换为 WGS84
    function bd09towgs84(lng, lat) {
        var ret = bd09togcj02(lng, lat);
        return gcj02towgs84(ret[0], ret[1]);
    }
    function transformlat(lng, lat) {
        var ret = -100.0 + 2.0 * lng + 3.0 * lat + 0.2 * lat * lat + 0.1 * lng * lat + 0.2 * Math.sqrt(Math.abs(lng));
        ret += (20.0 * Math.sin(6.0 * lng * PI) + 20.0 * Math.sin(2.0 * lng * PI)) * 2.0 / 3.0;
        ret += (20.0 * Math.sin(lat * PI) + 40.0 * Math.sin(lat / 3.0 * PI)) * 2.0 / 3.0;
        ret += (160.0 * Math.sin(lat / 12.0 * PI) + 320 * Math.sin(lat * PI / 30.0)) * 2.0 / 3.0;
        return ret;
    }
    function transformlng(lng, lat) {
        var ret = 300.0 + lng + 2.0 * lat + 0.1 * lng * lng + 0.1 * lng * lat + 0.1 * Math.sqrt(Math.abs(lng));
        ret += (20.0 * Math.sin(6.0 * lng * PI) + 20.0 * Math.sin(2.0 * lng * PI)) * 2.0 / 3.0;
        ret += (20.0 * Math.sin(lng * PI) + 40.0 * Math.sin(lng / 3.0 * PI)) * 2.0 / 3.0;
        ret += (150.0 * Math.sin(lng / 12.0 * PI) + 300.0 * Math.sin(lng / 30.0 * PI)) * 2.0 / 3.0;
        return ret;
    }
    Convert.bd09togcj02 = bd09togcj02;
    Convert.gcj02tobd09 = gcj02tobd09;
    Convert.wgs84togcj02 = wgs84togcj02;
    Convert.gcj02towgs84 = gcj02towgs84;
    Convert.wgs84tobd09 = wgs84tobd09;
    Convert.bd09towgs84 = bd09towgs84;

    return Convert;
});