define(["./HtmlElement"], function (HtmlElement) {
    'use strict';

    function InfoWindow(map, options) {
        // 调用基类构造函数
        HtmlElement.call(this, map, options);
        this.pixelOffset = Cesium.defaultValue(this.options.pixelOffset, new Cesium.Cartesian2(0, -20));// 像素偏移
    }

    // 继承基类
    InfoWindow.prototype = Object.create(HtmlElement.prototype);

    // 创建弹出框
    InfoWindow.prototype.createPopup = function () {
        // 创建信息框的主体
        this.popup = document.createElement("div");
        this.popup.className = "infoWindow";
        this.options.width ? this.popup.style.width = this.options.width + "px" : "";
        this.options.height ? this.popup.style.height = this.options.height + "px" : "";
        //创建关闭按钮
        if (this.options.closable) {
            var closer = document.createElement("span");
            closer.id = "popup-closer";
            closer.className = "infoWindow-closer";
            closer.onclick = () => {
                this.popup.style.display = "none";
                this.position = undefined;
                if (this.options.onClose) {
                    this.options.onClose();
                }
            };
            this.popup.appendChild(closer);
        }
        //创建标题
        this.title = document.createElement("div");
        this.title.className = "infoWindow-title";
        if (this.options.titleHtml != undefined) this.title.innerHTML = this.options.titleHtml;
        this.popup.appendChild(this.title);
        //创建存放信息的窗体内容
        this.content = document.createElement("div");
        if (this.options.contentHtml != undefined) this.content.innerHTML = this.options.contentHtml;
        this.popup.appendChild(this.content);
        return this.popup;
    }

    return InfoWindow;
});