define(["../utils/Convert"], function (Convert) {
    'use strict';

    function SceneTree(map, tree, resolve) {
        if (tree == undefined) {
            resolve && resolve();
            return;
        }
        this._map = map;
        if (typeof (tree) == "string") {
            fetch(tree).then((res) => {
                return res.json();
            }).then((tree) => {
                this._init(tree);
                resolve && resolve();
            });
        } else {
            this._init(tree);
            resolve && resolve();
        }
    }

    // 初始化
    SceneTree.prototype._init = function (tree) {
        this._tree = tree;
        var content = this._tree.content;
        // 清空影像层
        this._map.imageryLayers.removeAll();
        // 相机
        this._initCamera(content.cameraView.last);
        // 地形
        //this._initTerrain(content.terrain);
        // 天气
        this._initWeather(content.weather);
        // 后处理
        this._initPostProcess(content.postProcess);
        // 视图
        this._initView(content.view);
        // 场景树
        this._imageryLayers = new Array();// 记录栅格层和顺序
        this._terrainClips = new Array();// 记录挖洞
        this._currentFolder = content.sceneTree;
        this._initLayer(this._currentFolder);
        this._addImageryLayers();// 按序添加栅格层
        this._terrainClips.forEach(clip => { clip.clampToGround && clip._update() }), this._terrainClips.length = 0;// 地形加载后再更新挖洞
        // 裁剪
        this._map.scene.globe.clippingPolygonsDisplayFar = content.clippingPolygonsDisplayFar;
        this._initClipping(content.clipping);
    }
    // 初始视角
    SceneTree.prototype._initCamera = function (node) {
        if (!node) return;
        this._map.camera.setView({
            destination: Cesium.Cartesian3.fromDegrees(node.position[0], node.position[1], node.position[2]),
            orientation: new Cesium.HeadingPitchRoll(Cesium.Math.toRadians(node.rotation[0]), Cesium.Math.toRadians(node.rotation[1]), Cesium.Math.toRadians(node.rotation[2]))
        });
    }
    // 初始地形
    SceneTree.prototype._initTerrain = function (node) {
        if (!node) return;
        node.globeShow != undefined && (this._map.scene.globe.show = node.globeShow);
        node.enableLighting != undefined && (this._map.scene.globe.enableLighting = node.enableLighting);
        node.depthTest != undefined && (this._map.scene.globe.depthTestAgainstTerrain = node.depthTest);
        node.wireFrame != undefined && (this._map.cesiumInspector.viewModel.wireframe = node.wireFrame);
        if (node.globeTranslucency) {
            this._map.scene.frameState.globeTransparent = true;
            this._map.scene.globe.baseColor = Cesium.Color.TRANSPARENT;
        }
    }
    // 初始天气
    SceneTree.prototype._initWeather = function (node) {
        if (this._map.scene.sun) this._map.scene.sun.show = !node.sun || node.sun.enabled != false;
        if (this._map.scene.moon) this._map.scene.moon.show = !node.moon || node.moon.enabled != false;
        if (this._map.scene.skyAtmosphere) this._map.scene.skyAtmosphere.show = !node.atmosphere || node.atmosphere.enabled != false;
        this._map.setSkyBox(node.skyBox);
        if (this._map.scene.skyBox) this._map.scene.skyBox.show = !node.skyBox || node.skyBox.enabled != false;
    }
    // 初始后处理
    SceneTree.prototype._initPostProcess = function (node) {
        for (var key in node) {
            var val = node[key];
            if (val && val.enabled) val.object = this._json2Object(val);
        }
    }
    // 初始视图
    SceneTree.prototype._initView = function (node) {
        for (var k in node) {
            var v = node[k];
            this._map[k] = v;
        }
    }
    // 初始化场景树
    SceneTree.prototype._initLayer = function (node) {
        if (node.children) {
            if (node.children instanceof Array) {
                node.children.forEach(child => {
                    this._initLayer(child);
                })
            }
        } else {
            var obj = undefined;
            switch (node.type) {
                default:
                    obj = this._addObject(node);
                    break;
            }
        }
    }
    // 字符串转类
    // SceneTree.prototype._string2Class = function (clsName) {
    //     return new Function("return " + clsName)();
    // }
    // 添加对象
    SceneTree.prototype._json2Object = function (node) {
        var cls = new Function("return " + node.type)();
        var opts = Clone(node.params);// 参数//Convert.getOptions(Clone(node.params));
        if (node.type == 'Cesium.UrlTemplateImageryProvider') opts.tilingScheme = new ABCEarth.MyMercatorTilingScheme(opts);// 图层坐标转换
        if (cls && opts) {
            if (node.type == "Cesium.GeoJsonDataSource") return Cesium.GeoJsonDataSource.load(opts.url);
            return node.type.indexOf("Cesium.") >= 0 ? new cls(opts) : new cls(this._map, opts);
        }
    }
    // 创建对象
    SceneTree.prototype._addObject = function (node) {
        var obj = this._json2Object(node);
        if (!obj) return;
        node.object = obj;
        // cesium 原生对象添加
        var type = node.type, show = node.show != false;
        if (type.indexOf("Cesium.") >= 0) {
            if (type.indexOf("ImageryLayer") >= 0) {
                var provider = this._json2Object(node.params.imageryProvider);
                obj = new Cesium.ImageryLayer(provider, node.params);
                this._imageryLayers.push({ layer: obj, index: node.index });  //this._map.imageryLayers.add(obj, node.index);
                node.object = obj;
            } else if (type.indexOf("CesiumTerrainProvider") >= 0) {
                if (show) this._map.scene.terrainProvider = obj;
                show = undefined;
            } else if (type.indexOf("GeoJsonDataSource") >= 0) {
                (function (map, node, obj, show) {
                    obj.then(ds => { map.dataSources.add(ds), node.object = ds, ds.show = show });
                })(this._map, node, obj, show);// 异步所以闭包
                show = undefined;
            }
        } else if (type.indexOf("ABCEarth.") >= 0) {
            if (type.indexOf("TerrainClip") >= 0) this._terrainClips.push(obj);
        }
        if (show != undefined) obj.show = show;
    }
    // 按序添加栅格图层
    SceneTree.prototype._addImageryLayers = function () {
        // 升序
        if (this._imageryLayers.length > 1) {
            this._imageryLayers.sort((a, b) => {
                return a.index == b.index ? 0 : (a.index < b.index ? -1 : 1);
            });
        }
        // 添加
        this._imageryLayers.forEach(i => {
            this._map.imageryLayers.add(i.layer);
        });
    }
    // 设置当前文件夹
    SceneTree.prototype.setCurrentFolder = function (node) {
        this._currentFolder = node ? node : this._tree.content.sceneTree;
    }
    // 添加节点
    SceneTree.prototype.addNode = function (node) {
        this._currentFolder.children.push(node);
    }
    // 删除节点
    SceneTree.prototype.removeNode = function (parent, index) {
        parent = parent || this._tree.content.sceneTree;
        var node = parent.children[index];
        this._removeObject(node);
        parent.children.splice(index, 1);
    }
    // 删除节点关联模型
    SceneTree.prototype._removeObject = function (node) {
        if (node.type && node.object) {
            // if (node.type.indexOf("Cesium.") >= 0) {
            // } else {
            if (node.object.remove) node.object.remove();
            // }
        }
        if (node.children) {
            node.children.forEach(child => {
                this._removeObject(child);
            });
        }
    }
    // 遍历节点
    SceneTree.prototype.traverse = function (callback, node) {
        node = node || this._tree.content.sceneTree;
        if (callback && !callback(node)) return false;
        var children = node.children;
        if (children) {
            for (var i = 0, l = children.length; i < l; i++) {
                if (!this.traverse(callback, children[i])) return false;
            }
        }
        return true;// 是否继续遍历
    }
    // 裁剪
    SceneTree.prototype._initClipping = function (clipping) {
        if (!clipping) return;
        for (var key in clipping) {
            // 根据key查找多边形
            var pln = null;
            this.traverse((node) => {
                if (key == node.guid) pln = node.object;
                return pln == null;
            });
            // 找到则给关联的地形或模型赋值
            if (pln) {
                var clippingPolygon = null;
                var clip = clipping[key], ids = clip.target;
                for (var l = ids.length, i = l - 1; i >= 0; i--) {
                    var id = ids[i], obj = null;
                    // 地形
                    if (id == 'globe') {
                        obj = this._map.scene.globe;
                    }
                    // tilesets
                    else {
                        this.traverse((node) => {
                            if (id == node.guid) obj = node.object;
                            return obj == null;
                        });
                    }
                    if (obj) {
                        if (!obj.clippingPolygons) obj.clippingPolygons = new Cesium.ClippingPolygonCollection({ polygons: [] });
                        if (!clippingPolygon) clippingPolygon = new Cesium.ClippingPolygon({ positions: pln._positions, enabled: clip.enabled });
                        obj.clippingPolygons.add(clippingPolygon);
                    }
                    // 没找到则删除
                    else {
                        ids.splice(i, 1);
                    }
                }
            }
            // 没找到则删除
            else {
                delete clipping[key];
            }
        }
    }
    return SceneTree;
});