define(["../utils/License",
	"./WaterMark",
	"./MapEvent",
	"./MapType",
	"./SceneTree",
	"../controls/ContextMenu",
	"../utils/CommUtils",
	"../controls/MousePositionCtrl"],
	function (License, WaterMark, MapEvent, MapType, SceneTree, ContextMenu, CommUtils, MousePositionCtrl) {
		'use strict';
		/**
		 * 地图核心组件
		 * @container 页面地图容器id
		 * @options 地图相关选项
		 */
		function Map(container, options) {
			this._options = options = Cesium.defaultValue(options, {});
			options.animation = Cesium.defaultValue(options.animation, false); //是否显示动画控件
			options.shouldAnimate = Cesium.defaultValue(options.shouldAnimate, true); // 开启动画自动播放
			options.geocoder = Cesium.defaultValue(options.geocoder, false); //是否显示地名查找控件
			options.timeline = Cesium.defaultValue(options.timeline, true); //是否显示时间线控件
			options.sceneModePicker = Cesium.defaultValue(options.sceneModePicker, false); //是否显示投影方式(2d3d)控件
			options.navigationHelpButton = Cesium.defaultValue(options.navigationHelpButton, false); //是否显示帮助信息控件
			options.homeButton = Cesium.defaultValue(options.homeButton, false);// 是否显示Home控件
			options.baseLayerPicker = Cesium.defaultValue(options.baseLayerPicker, false); //是否显示图层选择控件
			options.viewBelow = Cesium.defaultValue(options.viewBelow, false);//是否支持相机进入地下视角
			options.antialias = Cesium.defaultValue(options.antialias, true);//是否开启抗锯齿
			options.fullscreenButton = Cesium.defaultValue(options.fullscreenButton, true);//全屏按钮
			options.mapProjection = Cesium.defaultValue(options.mapProjection, new Cesium.WebMercatorProjection());// 默认投影
			options.navigation = Cesium.defaultValue(options.navigation, true);// 导航控件
			// 背景图
			if (options.backgroundImage != undefined) {
				options.orderIndependentTranslucency = false;// 可忽略
				options.contextOptions = { webgl: { alpha: true, } };
			}
			// 默认底图
			if (options.imageryProvider == undefined) options.imageryProvider = MapType("NORMAL_ARCGIS_BLUE");
			// 调用基类构造函数
			Cesium.Viewer.call(this, container, options);
			// 背景图
			if (options.backgroundImage != undefined) {
				this.scene.backgroundColor = Cesium.Color.TRANSPARENT;// 背景透明
				this.scene.skyBox.show = false;// 隐藏天空盒
				this.scene.sun.show = false;// 隐藏太阳
				this.scene.moon.show = false;// 隐藏月亮
				this.container.style.backgroundImage = `url(${options.backgroundImage})`;
				this.container.style.backgroundRepeat = 'no-repeat';
				this.container.style.backgroundSize = '100% 100%';
			}
			// 默认天空盒
			this.defaultSkyBox = this.scene.skyBox;
			// 交换中右键
			this.SwitchMouseMiddleRight();
			// 初始化
			_init(this);
			// 初始化完成回调
			options.onLoad && options.onLoad();
		}
		// 继承基类
		Map.prototype = Object.create(Cesium.Viewer.prototype);
		// 定义属性
		Object.defineProperties(Map.prototype, {
			brightness: {// 亮度
				get() { return this.scene.brightness },
				set(value) {
					var stages = this.scene.postProcessStages;
					this.scene.brightness = this.scene.brightness || stages.add(Cesium.PostProcessStageLibrary.createBrightnessStage());
					this.scene.brightness.enabled = true;
					this.scene.brightness.uniforms.brightness = Number(value);
				}
			},
			//timelineCtrl: { get() { return this.timeline ? this.timeline.container : null } },// 引起时间轴不左对齐
			timelineCtrl: {
				get() {
					var elems = document.getElementsByClassName('cesium-timeline-main');
					return elems.length > 0 ? elems[0] : null;
				}
			},
			showTimeline: {// 时间轴
				get() { return this.timelineCtrl && this.timelineCtrl.style.visibility != "hidden" },
				set(value) {
					if (this.timelineCtrl) {
						this.timelineCtrl.style.visibility = value ? "visible" : "hidden";
						var state = Array.from(document.getElementsByClassName('mousePositionCtrl')).filter(i => i instanceof HTMLDivElement);
						state.length > 0 && (state[0].style.bottom = value ? '28px' : '0px');
						this.scaleCtrl && this.scaleCtrl.style.setProperty('bottom', value ? '28px' : '0px', 'important');
					}
				}
			},
			showState: {// 状态
				get() { return !!this._stateCtrl && this._stateCtrl.show },
				set(value) {
					if (value) this._stateCtrl = this._stateCtrl || new MousePositionCtrl(this);
					this._stateCtrl && (this._stateCtrl.show = value) && (this.timelineCtrl && (this.showTimeline = this.showTimeline));
				}
			},
			compassCtrl: { get() { return document.getElementById('distanceLegendDiv') } },
			showCompass: {// 罗盘
				get() { return this.compassCtrl && this.compassCtrl.style.visibility != "hidden" },
				set(value) { this.compassCtrl && (this.compassCtrl.style.visibility = value ? "visible" : "hidden") }
			},
			scaleCtrl: { get() { var arr = document.getElementsByClassName('distance-legend'); return arr.length > 0 ? arr[0] : null } },
			showScale: {// 比例尺
				get() { return this.scaleCtrl && this.scaleCtrl.style.visibility != "hidden" },
				set(value) { this.scaleCtrl && (this.scaleCtrl.style.visibility = value ? "visible" : "hidden") && (this.timelineCtrl && (this.showTimeline = this.showTimeline)) }
			}
		});
		// 修改鼠标操作习惯-交换中键右键
		Map.prototype.SwitchMouseMiddleRight = function () {
			this.scene.screenSpaceCameraController.tiltEventTypes = [
				Cesium.CameraEventType.RIGHT_DRAG, Cesium.CameraEventType.PINCH,
				{ eventType: Cesium.CameraEventType.LEFT_DRAG, modifier: Cesium.KeyboardEventModifier.CTRL },
				{ eventType: Cesium.CameraEventType.RIGHT_DRAG, modifier: Cesium.KeyboardEventModifier.CTRL }
			];
			this.scene.screenSpaceCameraController.zoomEventTypes = [Cesium.CameraEventType.MIDDLE_DRAG, Cesium.CameraEventType.WHEEL, Cesium.CameraEventType.PINCH];
		}
		// 从 Entity 获得 Model 的方法
		Map.prototype.getModelForEntity = function (entity) {
			var primitives = this.scene.primitives;
			for (var i = 0; i < primitives.length; i++) {
				var primitive = primitives.get(i);
				if (primitive instanceof Cesium.Model && primitive.id === entity) {
					return primitive;
				}
			}
			return null;
		};
		// 设置底图
		Map.prototype.setMapType = function (mapType) {
			var imagery = this.imageryLayers.get(0);
			this.imageryLayers.remove(imagery);
			this.imageryLayers.addImageryProvider(mapType, 0);
		};
		// 显示右键菜单
		Map.prototype.showContextMenu = function (items) {
			if (!this.contextMenu) {
				this.contextMenu = new ContextMenu(this);
			}
			this.contextMenu.show(items);
		}
		// 删除右键菜单
		Map.prototype.removeContextMenu = function () {
			if (this.contextMenu) this.contextMenu.remove();
		}
		// 设置天空盒
		Map.prototype.setSkyBox = function (options) {
			options = Cesium.defaultValue(options, {});
			if (options.custom) {// 自定义
				this.customSkyBox = this.scene.skyBox = new Cesium.SkyBox(options);
			} else {// 默认
				if (this.scene.skyBox != this.defaultSkyBox) this.scene.skyBox = this.defaultSkyBox;
			}
			if (options.custom && options.nearGround) {// 近地,添加监听事件
				if (!this.skyBoxListener) {
					this.skyBoxListener = () => {
						var e = this.camera.position;
						var ng = Cesium.Cartographic.fromCartesian(e).height < 2000;
						this.scene.skyBox = ng ? this.customSkyBox : this.defaultSkyBox;
						// this.scene.skyAtmosphere.show = !ng;
					}
					this.scene.postRender.addEventListener(this.skyBoxListener);
				}
			} else {// 非近地，删除监听事件
				if (this.skyBoxListener) {
					this.scene.postRender.removeEventListener(this.skyBoxListener);
					this.skyBoxListener = null;
				}
			}
			// this.scene.skyAtmosphere.show = !options.custom;
		}
		// 获取地图可视范围
		Map.prototype.getBound = function () {
			var viewBound = this.camera.computeViewRectangle();
			if (typeof viewBound === "undefined") {// 2D下拾取不到坐标, 所以做以下转换
				let canvas = this.scene.canvas;
				let upperLeft = new Cesium.Cartesian2(0, 0), lowerRight = new Cesium.Cartesian2(canvas.clientWidth, canvas.clientHeight);
				let ellipsoid = this.scene.globe.ellipsoid;
				let upperLeft3 = this.camera.pickEllipsoid(upperLeft, ellipsoid);//2D转3D世界坐标
				let lowerRight3 = this.camera.pickEllipsoid(lowerRight, ellipsoid);//2D转3D世界坐标
				let upperLeftCarto = this.scene.globe.ellipsoid.cartesianToCartographic(upperLeft3);//3D世界坐标转弧度
				let lowerRightCarto = this.scene.globe.ellipsoid.cartesianToCartographic(lowerRight3);//3D世界坐标转弧度
				viewBound = {
					east: lowerRightCarto.longitude,
					west: upperLeftCarto.longitude,
					south: lowerRightCarto.latitude,
					north: upperLeftCarto.latitude
				}
			}
			return {
				east: Cesium.Math.toDegrees(viewBound.east),
				west: Cesium.Math.toDegrees(viewBound.west),
				south: Cesium.Math.toDegrees(viewBound.south),
				north: Cesium.Math.toDegrees(viewBound.north)
			};// 东经, 西经, 南纬, 北纬
		};
		// 获取地图视图中心
		Map.prototype.getCenter = function () {
			var windowPosition = new Cesium.Cartesian2(this.container.clientWidth / 2, this.container.clientHeight / 2);
			var pickRay = this.scene.camera.getPickRay(windowPosition);
			var cartesian = this.scene.globe.pick(pickRay, this.scene);//var cartographic = this.scene.globe.ellipsoid.cartesianToCartographic(cartesian);
			return cartesian;
		};
		// 设置地图视图中心
		Map.prototype.setCenter = function (target, offset) {
			this.readyPromise.then(() => {
				target = CommUtils.AnglesToCartesian3(target);
				if (offset) {
					offset = CommUtils.AnglesToHeadingPitchRange(offset);
				} else {
					offset = new Cesium.HeadingPitchRange(this.camera.heading, this.camera.pitch, this.camera.positionCartographic.height);
				}
				this.camera.lookAt(target, offset);
				this.camera.lookAtTransform(Cesium.Matrix4.IDENTITY);
			});
		}
		// 设置地图正北方向
		Map.prototype.northView = function () {
			var center = this.getCenter();
			if (!center) return;
			var pitch = this.camera.pitch;
			var range = Cesium.Cartesian3.distance(center, this.camera.position);
			this.setCenter(center, new Cesium.HeadingPitchRange(0, pitch, range));
		}
		// 绕中心点旋转
		Map.prototype.rotateCenter = function (target, offset, delta) {
			if (this.rotateCenterListener) this.cancelRotateCenter();// 取消当前旋转
			target = CommUtils.AnglesToCartesian3(target);
			offset = CommUtils.AnglesToHeadingPitchRange(offset);
			if (!delta) delta = 0.05;
			this.setCenter(target, offset);
			this.rotateCenterListener = () => {
				offset.heading += Cesium.Math.toRadians(delta);
				offset.heading %= Cesium.Math.TWO_PI;
				offset.range = Cesium.Cartesian3.distance(target, this.camera.position);
				// offset.pitch = this.camera.pitch;// bug:每次pitch都会增加
				this.camera.lookAt(target, offset);
				this.camera.lookAtTransform(Cesium.Matrix4.IDENTITY);
			}
			this.scene.preRender.addEventListener(this.rotateCenterListener)
		}
		// 取消绕中心点旋转
		Map.prototype.cancelRotateCenter = function () {
			if (!this.rotateCenterListener) return;
			this.scene.preRender.removeEventListener(this.rotateCenterListener);
			this.rotateCenterListener = null;
		}
		// 销毁
		Map.prototype.destroy = function () {
			this._stateCtrl && this._stateCtrl.remove();// 状态栏
			this.cesiumNavigation && this.cesiumNavigation.destroy();// 指南针
			Cesium.Viewer.prototype.destroy.apply(this);
		}
		return Map;
		// 初始化
		function _init(map) {
			var options = map._options;
			// 光照(关闭时间对于模型亮度的影响)
			map.scene.light = new Cesium.DirectionalLight({
				direction: Cesium.defaultValue(options.lightDirection, new Cesium.Cartesian3(0.354925, -0.890918, -0.283358))
			});
			// 隐藏基类的版权图标
			map._cesiumWidget._creditContainer.style.display = 'none';//map._cesiumWidget._creditContainer.innerHTML = "";引起destroy错误
			// 支持线框模式
			map.extend(Cesium.viewerCesiumInspectorMixin);
			map.cesiumInspector.container.style.display = "none";
			// 注册地图事件
			map.mapEvent = new MapEvent(map);
			// 设置地图中心点
			if (options.center) map.setCenter(options.center.target, options.center.offset);
			// 限制地下视角
			map.scene.screenSpaceCameraController.viewBelow = options.viewBelow;
			map.scene.screenSpaceCameraController.viewpitch = -0.15;
			// 是否开启抗锯齿
			if (options.antialias) {
				if (Cesium.FeatureDetection.supportsImageRenderingPixelated()) {//判断是否支持图像渲染像素化处理
					map.resolutionScale = window.devicePixelRatio;
				}
				map.scene.fxaa = true;
				map.scene.postProcessStages.fxaa.enabled = true;
				// var supportsImageRenderingPixelated = map.cesiumWidget._supportsImageRenderingPixelated;
				// if (supportsImageRenderingPixelated) {
				//     var vtxf_dpr = window.devicePixelRatio;
				//     while (vtxf_dpr >= 2.0) { vtxf_dpr /= 2.0; }
				//     map.resolutionScale = vtxf_dpr;
				// }
			}
			// 导航控件
			if (Cesium.viewerCesiumNavigationMixin && map._options.navigation) {
				var naviParams = map._options.navigation;
				map.extend(Cesium.viewerCesiumNavigationMixin, {
					defaultResetView: Cesium.defaultValue(naviParams.defaultResetView, Cesium.Cartographic.fromDegrees(110, 38, 9000000)),// 默认视图。接受的值是Cesium.Cartographic 和Cesium.Rectangle.
					enableCompass: Cesium.defaultValue(naviParams.enableCompass, true),// 启用或禁用罗盘
					enableZoomControls: Cesium.defaultValue(naviParams.enableZoomControls, true),// 启用或禁用缩放控件
					enableDistanceLegend: Cesium.defaultValue(naviParams.enableDistanceLegend, true),// 启用或禁用距离图例
					enableCompassOuterRing: Cesium.defaultValue(naviParams.enableCompassOuterRing, true),// 启用或禁用指南针外环。如果将选项设置为false，则该环将可见但无效。
				});
			}
			// 水印
			License.valid().catch(error => {
				var waterMark = new WaterMark(map);
			});
			// 添加相机移动函数
			_addCameraMoveTo(map);
			// 场景树
			map.readyPromise = new Promise((resolve, reject) => {
				map.sceneTree = new SceneTree(map, options.sceneTree, resolve);
			});
		}
		// 添加相机移动函数
		function _addCameraMoveTo(map) {
			var camera = map.camera, _flyHandler = null;
			camera.moveTo = (options) => {
				map.clock.onTick.removeEventListener(_flyHandler);
				if (options == undefined) return;
				var duration = options.duration || 0, duration = Math.max(duration, 0) * 1000, orientation = options.orientation || new Cesium.HeadingPitchRoll(0, 0, 0);
				var turnDuration = options.turnDuration == undefined ? duration : Math.min(duration, options.turnDuration * 1000);
				var time0 = Date.now(), position0 = camera.position.clone(), heading0 = camera.heading % Cesium.Math.TWO_PI, pitch0 = camera.pitch % Cesium.Math.TWO_PI, roll0 = camera.roll % Cesium.Math.TWO_PI;
				var heading = orientation.heading % Cesium.Math.TWO_PI, pitch = orientation.pitch % Cesium.Math.TWO_PI, roll = orientation.roll % Cesium.Math.TWO_PI;
				// 最近路线逼近，防止翻滚
				Math.abs(heading0 - heading) > Cesium.Math.PI && ((heading0 < heading) ? (heading0 += Cesium.Math.TWO_PI) : (heading += Cesium.Math.TWO_PI));
				Math.abs(pitch0 - pitch) > Cesium.Math.PI && ((pitch0 < pitch) ? (pitch0 += Cesium.Math.TWO_PI) : (pitch += Cesium.Math.TWO_PI));
				Math.abs(roll0 - roll) > Cesium.Math.PI && ((roll0 < roll) ? (roll0 += Cesium.Math.TWO_PI) : (roll += Cesium.Math.TWO_PI));
				_flyHandler = () => {
					var past = (Date.now() - time0), scale = past >= duration ? 1 : (past / duration), turnScale = past >= turnDuration ? 1 : (past / turnDuration);
					camera.setView({
						destination: Cesium.Cartesian3.add(
							Cesium.Cartesian3.multiplyByScalar(position0, 1 - scale, new Cesium.Cartesian3),
							Cesium.Cartesian3.multiplyByScalar(options.destination, scale, new Cesium.Cartesian3),
							new Cesium.Cartesian3),
						orientation: {
							heading: heading0 * (1 - turnScale) + heading * turnScale,
							pitch: pitch0 * (1 - turnScale) + pitch * turnScale,
							roll: roll0 * (1 - turnScale) + roll * turnScale
						},
					})
					if (past >= duration) {
						map.clock.onTick.removeEventListener(_flyHandler);
						if (options.complete) options.complete();
					}
				}
				map.clock.onTick.addEventListener(_flyHandler);
			}
		}
	});