define(["../ABCEarth",
    "./CommUtils",
    "./Convert"
], function (ABCEarth, CommUtils, Convert) {
    ABCEarth.CommUtils = CommUtils;
    ABCEarth.Convert = Convert;
    // 克隆
    window.Clone = function (obj) {
        var copy = (obj instanceof Array) ? [] : {};
        for (attr in obj) {
            if (!obj.hasOwnProperty(attr)) continue;
            copy[attr] = (typeof obj[attr] == "object") && obj[attr] != null ? Clone(obj[attr]) : obj[attr];
        }
        return copy;
    };
});
