        // 计算两点的贴地形距离
        getTerrainDistance: function (map, cartographic1, cartographic2, callback) {
            var geodesic = new Cesium.EllipsoidGeodesic();
            geodesic.setEndPoints(cartographic1, cartographic2);
            var s = geodesic.surfaceDistance;
            var space = Math.max(1.0, s / 100.0);
            var cartoPts = [cartographic1];
            for (var i = space; i < s; i += space) {// 分段采样计算距离
                var cartoPt = geodesic.interpolateUsingSurfaceDistance(i);
                cartoPts.push(cartoPt);
            }
            cartoPts.push(cartographic2);
            // 返回两点之间的距离
            var promise = Cesium.sampleTerrainMostDetailed(map.terrainProvider, cartoPts);//Cesium.sampleTerrain(map.terrainProvider, 8, cartoPts);
            Cesium.when(promise, function (updatedPositions) {
                var distance = 0;
                for (var i = 0; i < updatedPositions.length - 1; i++) {
                    var co1 = updatedPositions[i], co2 = updatedPositions[i + 1];
                    var geoD = new Cesium.EllipsoidGeodesic();
                    geoD.setEndPoints(co1, co2);
                    var innerS = geoD.surfaceDistance;
                    innerS = Math.sqrt(Math.pow(innerS, 2) + Math.pow(co2.height - co1.height, 2));
                    distance += innerS;
                    // 与直线距离稍差一点
                    // var ce1 = Cesium.Cartesian3.fromRadians(co1.longitude, co1.latitude, co1.height);
                    // var ce2 = Cesium.Cartesian3.fromRadians(co2.longitude, co2.latitude, co2.height);
                    // distance += Cesium.Cartesian3.distance(ce1, ce2);
                }
                callback(distance);
            });
        },
        // 计算表面距离
        getSurfaceDistance: function (carto1, carto2) {
            // 根据经纬度计算出距离
            var geodesic = new Cesium.EllipsoidGeodesic();
            geodesic.setEndPoints(carto1, carto2);
            var s = geodesic.surfaceDistance;
            // 返回两点之间的距离
            s = Math.sqrt(Math.pow(s, 2) + Math.pow(carto2.height - carto1.height, 2));
            return s;
        },
        // 计算多边形空间面积
        getSpatialArea: function (carteArray) {
            var radius = 6371008.8;
            var area = 0, len = carteArray.length;
            if (len < 3) return 0;
            var carto1 = Cesium.Cartographic.fromCartesian(carteArray[len - 1]);
            var x1 = carto1.longitude;
            var y1 = carto1.latitude;
            for (var i = 0; i < len; i++) {
                var cartoi = Cesium.Cartographic.fromCartesian(carteArray[i]);
                var x2 = cartoi.longitude, y2 = cartoi.latitude;
                area += (x2 - x1) * (2 + Math.sin(y1) + Math.sin(y2));
                x1 = x2;
                y1 = y2;
            }
            area = area * radius * radius / 2.0;
            area = Math.abs(area);
            return area;
        },
