        // 高度转层级
        altitudeToZoom: function (altitude) {
            var A = 40487.57;
            var B = 0.00007096758;
            var C = 91610.74;
            var D = -40467.74;
            var L = D + (A - D) / (1 + Math.pow(altitude / C, B));
            return Math.round(L);
        },
        // 计算坐标串外接矩形，数据格式[[x,y],[x,y]......]
        getBounds: function (points) {
            var xmin, ymin, xmax, ymax;
            for (var i = 0, len = points.length; i < len; i++) {
                var p = points[i], x = p[0], y = p[1];
                xmin = i == 0 ? x : Math.min(xmin, x);
                ymin = i == 0 ? y : Math.min(ymin, y);
                xmax = i == 0 ? x : Math.max(xmax, x);
                ymax = i == 0 ? y : Math.max(ymax, y);
            }
            return {
                west: xmin, south: ymin, east: xmax, north: ymax,
                xmin: xmin, ymin: ymin, xmax: xmax, ymax: ymax
            }
        },
