define(function () {
    'use strict';

    function WaterMark(map, options) {
        options = options || {};
        this._map = map;
        this._name = '0b79e81a-d03a-6a36-37ae-28dbbd50293b';
        this._text = Cesium.defaultValue(options.text, 'ABCEarth');// 内容 ABCEarth Trial Version
        this._fontSize = Cesium.defaultValue(options.font, 50);// 字体大小
        this._color = Cesium.defaultValue(options.color, "rgb(255,255,255,1)");// 颜色
        this._checkStage();
    }

    // 检查后处理
    WaterMark.prototype._checkStage = function () {
        if (this._map.scene.postProcessStages.getStageByName(this._name) == undefined) {
            this._map.scene.postProcessStages.add(this._getStage());
        }
        setTimeout(() => {
            this._checkStage();
        }, 10000);
    }

    // 获取水印图片
    WaterMark.prototype._getImage = function () {
        var canvas = document.createElement("canvas");
        canvas.width = this._map.canvas.width, canvas.height = this._map.canvas.height;
        var context = canvas.getContext('2d');
        context.font = `${this._fontSize}px Arial`;
        context.fillStyle = this._color;
        var x = (canvas.width - this._text.length * this._fontSize / 2.0) / 2.0;
        var y = (canvas.height - this._fontSize) / 2.0;
        context.fillText(this._text, x, y);
        context.restore();
        return canvas.toDataURL("image/png");
    }

    // 获取后处理
    WaterMark.prototype._getStage = function () {
        if (!this._stage || this._stage.isDestroyed()) {
            this._map.scene.postProcessStages.remove(this._stage);
            var image = this._getImage();
            this._stage = new Cesium.PostProcessStage({
                name: this._name,
                fragmentShader: "uniform sampler2D colorTexture;\n\
                    in vec2 v_textureCoordinates;\n\
                    uniform sampler2D image;\n\
                    void main() {\n\
                        vec4 color = texture(colorTexture, v_textureCoordinates);\n\
                        vec4 imageColor = texture(image, v_textureCoordinates);\n\
                        out_FragColor = mix(color, imageColor, 0.1);\n\
                    }",
                uniforms: {
                    image: image
                }
            });
        }
        return this._stage;
    }

    return WaterMark;
});
