define(['../core/EventType', '../utils/CommUtils'], function (EventType, CommUtils) {
    'use strict';
    function MousePositionCtrl(map) {
        this._map = map;
        // 创建控件容器
        this._container = document.createElement("div");
        this._container.className = "mousePositionCtrl";
        map.container.appendChild(this._container);
        // 鼠标信息
        this._mouseCtrl = document.createElement("span");
        this._mouseCtrl.className = "mousePositionCtrl";
        this._container.appendChild(this._mouseCtrl);
        // 相机信息
        this._cameraCtrl = document.createElement("span");
        this._cameraCtrl.className = "mousePositionCtrl";
        this._container.appendChild(this._cameraCtrl);
        // 渲染信息
        this._renderCtrl = document.createElement("span");
        this._renderCtrl.className = "mousePositionCtrl";
        this._container.appendChild(this._renderCtrl);
        // 鼠标移动事件
        this._mouseMove = (event) => {
            if (!event.degrees) return;
            var lng = event.degrees.lng.toFixed(6), lat = event.degrees.lat.toFixed(6), alt = event.degrees.alt.toFixed(1);
            this._mouseCtrl.innerHTML = `经度：${lng}&nbsp;&nbsp;&nbsp;纬度：${lat}&nbsp;&nbsp;&nbsp;海拔：${alt}米&nbsp;&nbsp;&nbsp;`;
        };
        map.addEventListener(EventType.MOUSE_MOVE, this._mouseMove);
        // 缩放结束事件
        this._moveEnd = () => {
            var height = Math.ceil(map.camera.positionCartographic.height);
            var zoom = CommUtils.altitudeToZoom(height);
            var heading = Math.round(Cesium.Math.toDegrees(map.camera.heading)) % 360;
            var pitch = Math.round(Cesium.Math.toDegrees(map.camera.pitch));
            this._cameraCtrl.innerHTML = `方向：${heading}度&nbsp;&nbsp;&nbsp;俯仰角：${pitch}度&nbsp;&nbsp;&nbsp;视高：${height}米&nbsp;&nbsp;&nbsp;层级：${zoom}&nbsp;&nbsp;&nbsp;`;
        };
        map.scene.camera.moveEnd.addEventListener(this._moveEnd);
        // 渲染完成事件
        var _prevRender = Date.now(), _preSeconds = Math.round(_prevRender / 1000);
        this._postRender = () => {
            var render = Date.now(), seconds = Math.round(render / 1000);
            var span = render - _prevRender;
            var rate = Math.round(1000 / span);
            if (_preSeconds != seconds) {
                _preSeconds = seconds;
                this._renderCtrl.innerHTML = `帧率：${rate}`;
            }
            _prevRender = render;
        };
        map.scene.postRender.addEventListener(this._postRender);
    }
    // 属性
    Object.defineProperties(MousePositionCtrl.prototype, {
        show: {
            get() { return this._container.style.display != "none" },
            set(value) { this._container.style.display = value ? "block" : "none" }
        }
    });
    // 删除
    MousePositionCtrl.prototype.remove = function () {
        this._map.removeEventListener(EventType.MOUSE_MOVE, this._mouseMove);
        this._map.scene.camera.moveEnd.removeEventListener(this._moveEnd);
        this._map.scene.postRender.removeEventListener(this._postRender);
        this._map.container.removeChild(this._container);
    }
    return MousePositionCtrl;
});