define(["../utils/CommUtils"], function (CommUtils) {
	'use strict';

	function HtmlElement(map, options) {
		this.map = map;
		this.options = Cesium.defaultValue(options, {});
		this.position = this.options.position;
		// 偏移量
		this.pixelOffset = Cesium.defaultValue(this.options.pixelOffset, new Cesium.Cartesian2(0, 0));// 像素偏移
		this.eyeOffset = Cesium.defaultValue(this.options.eyeOffset, new Cesium.Cartesian3(0, 0, 0));// 视角偏移
		// 创建弹出框
		this.popup = this.createPopup();
		this.map.container.appendChild(this.popup);
		//定阅实时渲染事件
		this.callback = (s, t) => { this.update(); }
		this.map.scene.postRender.addEventListener(this.callback);
		// 内容属性
		Object.defineProperty(this, "contentHtml", {
			get: function () {
				return this.content.innerHTML;
			},
			set: function (value) {
				this.content.innerHTML = value;
			}
		});
		// 是否可见
		Object.defineProperty(this, "show", {
			get: function () {
				return this.popup && this.popup.style.display != "none";
			},
			set: function (value) {
				if (!this.popup) return;
				this.popup.style.display = value ? "block" : "none";
			}
		});
		if (this.options.show != undefined) this.show = this.options.show;
		// 事件回调
		if (this.options.onMouseOver) this.popup.onmouseover = (e) => { this.options.onMouseOver(e, this.options) };
		if (this.options.onMouseOut) this.popup.onmouseout = (e) => { this.options.onMouseOut(e, this.options) };
		if (this.options.onClick) this.popup.onclick = (e) => { this.options.onClick(e, this.options) };
	}

	// 创建弹出框
	HtmlElement.prototype.createPopup = function () {
		this.popup = this.content = document.createElement("div");//popup = map._container.append("div");
		Object.assign(this.popup.style, { position: "absolute", left: "0px", top: "0px" });// popup.style = { position: "absolute", left: "0px", top: "0px" };
		this.popup.style.position = 'absolute';
		this.popup.innerHTML = this.options.contentHtml;// 嵌入的HTML代码 // popup.append(options.contentHtml);// 嵌入的HTML代码
		return this.popup;
	}

	// 实时更新信息框位置
	HtmlElement.prototype.update = function () {
		//实时转换信息框的坐标标
		var position = this.position;
		if (position !== undefined) {
			var cartsain = CommUtils.AnglesToCartesian3(position);// var cartsain = position instanceof Cesium.Cartesian3 ? position : position._value;
			var pixel = this.map.scene.cartesianWithEyeOffsetToCanvasCoordinates(cartsain, this.eyeOffset);//var pixel = Cesium.SceneTransforms.wgs84ToWindowCoordinates(this.map.scene, cartsain);
			if (pixel && pixel.x) {
				var x = pixel.x - (this.popup.offsetWidth) / 2;// var x = pixel.x;// - (this.popup.offsetWidth) / 2;
				var y = pixel.y - (this.popup.offsetHeight);// var y = pixel.y;// - (this.popup.offsetHeight);
				x += this.pixelOffset.x;
				y += this.pixelOffset.y;
				this.popup.style.transform = 'translate3d(' + x + 'px, ' + y + 'px, 0)';
			}
			//控制在地球背面时，隐藏div
			// var camPos = this.map.camera.position;
			// var height = this.map.scene.globe.ellipsoid.cartesianToCartographic(position).height;
			// if (!(height += 1 * this.map.scene.globe.ellipsoid.maximumRadius, Cesium.Cartesian3.distance(camPos, position) > height)) {
			// 	this.popup.style.display = "block";
			// } else {
			// 	this.popup.style.display = "none";
			// }
		}
	};

	// 删除
	HtmlElement.prototype.remove = function () {
		if (!this.popup) return;
		this.map.scene.postRender.removeEventListener(this.callback);
		this.map.container.removeChild(this.popup);
		this.popup = undefined;
	}

	return HtmlElement;
});
