define(["./EventType", "../utils/Convert"], function (EventType, Convert) {
    'use strict';

    function MapEvent(map) {
        this._map = map;
        // 取消cesium默认单击双击事件
        map.cesiumWidget.screenSpaceEventHandler.removeInputAction(Cesium.ScreenSpaceEventType.LEFT_CLICK);
        map.cesiumWidget.screenSpaceEventHandler.removeInputAction(Cesium.ScreenSpaceEventType.LEFT_DOUBLE_CLICK);
        // 地图事件处理的集合
        this._listeners = new Map();
        // this._listeners = {
        //     LeftClick: [],// 左键单击
        //     LeftDbClick: [],// 左键双击
        //     RightClick: [],// 右键单击
        //     MouseMove: [],// 鼠标移动
        //     CameraMoveEnd: [],// 相机移动结束事件
        // };
        this._init();
    }
    // 初始化
    MapEvent.prototype._init = function () {
        var map = this._map;
        this._register();
        // 注册地图视图操作事件
        map.addEventListener = map.on = (type, handler) => {
            var listeners = this._listeners.get(type);
            if (!listeners) {
                listeners = new Array();
                this._listeners.set(type, listeners);
            }
            listeners.push(handler);
        }
        // 注销消息
        map.removeEventListener = map.off = (type, handler) => {
            var listeners = this._listeners.get(type);
            if (listeners) {
                var index = listeners.indexOf(handler);
                index > -1 && listeners.splice(index, 1);
            }
        }
    }
    // 注册事件
    MapEvent.prototype._register = function () {
        var map = this._map;
        var handler = new Cesium.ScreenSpaceEventHandler(map.scene.canvas);
        // 鼠标左键单双击事件
        handler.setInputAction((e) => {
            if (this._clickTimer != null) {// 双击
                clearTimeout(this._clickTimer);
                this._clickTimer = null;
                var event = this._mapScenePick(e.position);
                this._fireMapEvent(EventType.LEFT_DBCLICK, event);// 触发地图事件
            } else {// 单击
                this._clickTimer = setTimeout(() => {
                    this._clickTimer = null;
                    map.removeContextMenu();// 删除右键菜单
                    var event = this._mapScenePick(e.position);
                    // 触发图元事件
                    if (event.feature && event.feature.click) {
                        event.feature.click(event);
                    }
                    // 触发地图事件
                    this._fireMapEvent(EventType.LEFT_CLICK, event);
                }, 200);
            }
        }, Cesium.ScreenSpaceEventType.LEFT_CLICK);
        // handler.setInputAction((e) => {
        //     window.clearInterval(this._clickTimerId);
        //     this._clickTimerId = window.setTimeout(() => {
        //         map.removeContextMenu();// 删除右键菜单
        //         var event = this._mapScenePick(e.position);
        //         // 触发图元事件
        //         if (event.feature && event.feature.click) {
        //             event.feature.click(event);
        //         }
        //         // 触发地图事件
        //         this._fireMapEvent(EventType.LEFT_CLICK, event);
        //     }, 200);
        // }, Cesium.ScreenSpaceEventType.LEFT_CLICK);
        // // 鼠标左键双击事件
        // handler.setInputAction((e) => {
        //     window.clearInterval(this._clickTimerId);
        //     var event = this._mapScenePick(e.position);
        //     this._fireMapEvent(EventType.LEFT_DBCLICK, event);// 触发地图事件
        // }, Cesium.ScreenSpaceEventType.LEFT_DOUBLE_CLICK);
        // 鼠标右键单击事件
        handler.setInputAction((e) => {
            map.removeContextMenu();// 删除右键菜单
            var event = this._mapScenePick(e.position);
            this._fireFeatureEvent('rightClick', event);// 触发图元事件
            this._fireMapEvent(EventType.RIGHT_CLICK, event);// 触发地图事件
        }, Cesium.ScreenSpaceEventType.RIGHT_CLICK);
        // 左键按下
        handler.setInputAction((e) => {
            this._dragging = this._mapScenePick(e.position);
            this._fireFeatureEvent('dragStart', this._dragging);// 触发图元事件
            this._fireMapEvent(EventType.DRAG_START, this._dragging);// 触发地图事件
        }, Cesium.ScreenSpaceEventType.LEFT_DOWN);
        // 左键弹起
        handler.setInputAction((e) => {
            this._fireFeatureEvent('dragEnd', this._dragging);// 触发图元事件
            this._fireMapEvent(EventType.DRAG_END, this._dragging);// 触发地图事件
            this._dragging = undefined;
        }, Cesium.ScreenSpaceEventType.LEFT_UP);
        // 鼠标移动事件
        handler.setInputAction((e) => {
            if (this._clickTimer != null) return;
            if (this._dragging) {// 正在拖动
                this._setPositionValue(this._dragging, e.endPosition);
                this._fireFeatureEvent('dragging', this._dragging);// 触发图元事件
                this._fireMapEvent(EventType.DRAGGING, this._dragging);// 触发地图事件
            } else {
                window.clearInterval(this._mouseMoveTimerId);
                this._mouseMoveTimerId = window.setTimeout(() => {
                    var event = this._mapScenePick(e.endPosition);
                    this._fireMapEvent(EventType.MOUSE_MOVE, event);// 触发地图事件
                    // 触发图元事件
                    if (Cesium.defined(event.feature)) {
                        // 移出事件
                        if (this.curFeature && this.curFeature.mouseout && this.curFeature != event.feature) {
                            this.curFeature.mouseout({ feature: this.curFeature });
                        }
                        // 移入事件
                        if (event.feature.mouseover && this.curFeature != event.feature) {
                            event.feature.mouseover(event);
                        }
                        // 移动事件
                        if (event.feature.mousemove) {
                            event.feature.mousemove(event);
                        }
                        this.curFeature = event.feature;
                    } else {
                        // 移出事件
                        if (this.curFeature && this.curFeature.mouseout) {
                            this.curFeature.mouseout({ feature: this.curFeature });
                        }
                        this.curFeature = undefined;
                    }
                }, 0);//30
            }
            // 闭包处理
            // this._mouseMoveTimerId = (function (map, event) {
            //     return window.setTimeout(function () {
            //         _scenePick(map, event, event.endPosition);
            //         this._listeners.MouseMove.forEach(listener => {
            //             listener(event);
            //         });
            //     }, 30);
            // })(map, event);
            // }
        }, Cesium.ScreenSpaceEventType.MOUSE_MOVE);
        /*
         * 相机移动结束事件，同步为地图视野变化事件
         * */
        map.scene.camera.moveEnd.addEventListener(() => {
            // 触发地图事件
            this._fireMapEvent(EventType.CAMERA_MOVE_END);
        });
    }
    // 触发地图事件
    MapEvent.prototype._fireMapEvent = function (type, e) {
        var listeners = this._listeners.get(type);
        listeners && listeners.forEach(listener => {
            listener(e);
        });
    }
    // 触发图元事件
    MapEvent.prototype._fireFeatureEvent = function (type, e) {
        e.feature && e.feature[type] && e.feature[type](e);
    }
    // 场景拾取
    MapEvent.prototype._mapScenePick = function (position) {
        var map = this._map;
        var event = {};
        event.screen = position;
        event.picked = map.scene.pick(position);
        if (event.picked) event.feature = event.picked.id && !Array.isArray(event.picked.id) ? event.picked.id : event.picked.primitive;// 实体（数组是点聚合对象）
        this._setPositionValue(event, position);
        return event;
    }
    // 设置坐标信息
    MapEvent.prototype._setPositionValue = function (obj, position) {
        var map = this._map;
        obj.screen = position;
        // var cartesian = obj.picked && !this._dragging ? map.scene.pickPosition(position) : map.scene.globe.pick(map.scene.camera.getPickRay(position), map.scene);
        var cartesian = Convert.screenToWorld(map, position);
        if (cartesian) {
            obj.cartesian = cartesian.clone();
            obj.degrees = this._cartesianToDegrees(cartesian);
        }
    }
    // Cartesian转经纬度
    MapEvent.prototype._cartesianToDegrees = function (cartesian) {
        if (cartesian) {
            var cartographic = Cesium.Cartographic.fromCartesian(cartesian);
            return {
                lng: Cesium.Math.toDegrees(cartographic.longitude),
                lat: Cesium.Math.toDegrees(cartographic.latitude),
                alt: cartographic.height
            };
        }
        return undefined;
    }
    return MapEvent;
});